import { useEffect, useRef, useState, useSyncExternalStore, type CSSProperties } from 'react';
import { motion, type MotionStyle } from 'motion/react';
import { Pause, Play } from 'lucide-react';

/**
 * Born-style full-bleed background video: monochrome, muted, looping, decorative.
 * Clips live in public/videos (generated by scripts/encode-videos.sh) as
 * <name>-1080.mp4, <name>-720.mp4 and <name>-poster.jpg.
 */
export type VideoName = 'cliff' | 'clouds' | 'coast' | 'road';

/* ---- One shared play/pause state for every background video (WCAG 2.2.2) ---- */
const reducedQuery = typeof window !== 'undefined' ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
let paused = !!reducedQuery?.matches;
const listeners = new Set<() => void>();
const subscribe = (l: () => void) => (listeners.add(l), () => listeners.delete(l));
const setPaused = (v: boolean) => {
  paused = v;
  listeners.forEach((l) => l());
};
export const useVideosPaused = () => useSyncExternalStore(subscribe, () => paused, () => true);

function pickSize() {
  if (typeof window === 'undefined') return '720';
  const conn = (navigator as Navigator & { connection?: { saveData?: boolean } }).connection;
  return window.matchMedia('(min-width: 1024px)').matches && !conn?.saveData ? '1080' : '720';
}

interface VideoBgProps {
  name: VideoName;
  className?: string;
  /** Extra condition for playback (e.g. a sticky hero that is covered but still "in view"). */
  active?: boolean;
  /** Load eagerly (first-viewport hero). */
  priority?: boolean;
  style?: MotionStyle;
}

export function VideoBg({ name, className = '', active = true, priority = false, style }: VideoBgProps) {
  const ref = useRef<HTMLVideoElement>(null);
  const [inView, setInView] = useState(priority);
  const [size] = useState(pickSize);
  const isPaused = useVideosPaused();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(([e]) => setInView(e.isIntersecting), { rootMargin: '200px 0px' });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const shouldPlay = inView && active && !isPaused;
    if (shouldPlay) el.play().catch(() => {});
    else el.pause();
    if (!shouldPlay) return;
    // Clips are encoded to loop seamlessly; keep them going if a browser ever stops at the end,
    // drops `loop`, or suspends playback while the tab is hidden.
    const restart = () => {
      el.currentTime = 0;
      el.play().catch(() => {});
    };
    const resume = () => {
      if (document.visibilityState === 'visible' && el.paused) el.play().catch(() => {});
    };
    el.addEventListener('ended', restart);
    document.addEventListener('visibilitychange', resume);
    return () => {
      el.removeEventListener('ended', restart);
      document.removeEventListener('visibilitychange', resume);
    };
  }, [inView, active, isPaused]);

  return (
    <motion.div aria-hidden="true" className={`pointer-events-none absolute inset-0 overflow-hidden ${className}`} style={style}>
      <video
        ref={ref}
        className="h-full w-full object-cover"
        src={`/videos/${name}-${size}.mp4`}
        poster={`/videos/${name}-poster.jpg`}
        muted
        loop
        playsInline
        preload={priority ? 'auto' : 'metadata'}
        tabIndex={-1}
        disablePictureInPicture
      />
    </motion.div>
  );
}

/** Small caps toggle that pauses/plays all background videos. */
export function VideoToggle({ className = '', style }: { className?: string; style?: CSSProperties }) {
  const isPaused = useVideosPaused();
  return (
    <button
      type="button"
      onClick={() => setPaused(!isPaused)}
      aria-pressed={isPaused}
      className={`dna-tag inline-flex min-h-11 items-center gap-2 opacity-80 hover:opacity-100 ${className}`}
      style={style}
    >
      {isPaused ? <Play className="h-3.5 w-3.5" strokeWidth={1.5} /> : <Pause className="h-3.5 w-3.5" strokeWidth={1.5} />}
      {isPaused ? 'Play' : 'Pause'} video
    </button>
  );
}
